from typing import List, Dict, Tuple

class SimpleTokenizer:
    """
    A vocabulary-based subword and word tokenizer with special token support.
    """
    def __init__(self, vocab: List[str] = None):
        self.special_tokens = ["<PAD>", "<UNK>", "<BOS>", "<EOS>"]
        if vocab is None:
            vocab = []

        all_tokens = list(self.special_tokens)
        for token in vocab:
            if token not in all_tokens:
                all_tokens.append(token)

        self.token2id: Dict[str, int] = {t: i for i, t in enumerate(all_tokens)}
        self.id2token: Dict[int, str] = {i: t for i, t in enumerate(all_tokens)}

    def __len__(self) -> int:
        return len(self.token2id)

    def encode(self, text: str) -> List[int]:
        words = text.split()
        unk_id = self.token2id.get("<UNK>", 1)
        return [self.token2id.get(w, unk_id) for w in words]

    def decode(self, token_ids: List[int]) -> str:
        ignore = {"<PAD>", "<BOS>", "<EOS>"}
        words = []
        for tid in token_ids:
            tok = self.id2token.get(tid, "")
            if tok and tok not in ignore:
                words.append(tok)
        return " ".join(words)

    @staticmethod
    def get_stats(vocab_splits: Dict[str, int]) -> Dict[Tuple[str, str], int]:
        pairs: Dict[Tuple[str, str], int] = {}
        for word, freq in vocab_splits.items():
            symbols = word.split()
            for i in range(len(symbols) - 1):
                pair = (symbols[i], symbols[i + 1])
                pairs[pair] = pairs.get(pair, 0) + freq
        return pairs
